import {renderStaffPortal,adminTaskForm,bindAdminTaskForm} from './staff.js';
let otpEmail='',recoveryToken='';
import {renderCustomerPortal} from './customer-portal.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#editor');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<span class="material-symbols-outlined" aria-hidden="true">${n}</span>`;
const initials=n=>String(n||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const money=(n,currency=reportCurrency)=>new Intl.NumberFormat('en-IN',{style:'currency',currency,maximumFractionDigits:2}).format(Number(n||0));
const today=()=>new Date().toISOString().slice(0,10);
const titles={store:'Products & plans',overview:'Overview',subscriptions:'Subscriptions',quotationTemplates:'Quotation templates',quotations:'Quotations',invoices:'Invoices',payments:'Payments',products:'Products',plans:'Plans',customers:'Customers',discounts:'Discounts',taxes:'Taxes',reports:'Reports',profile:'Your account',team:'Team access',adminCustomers:'Customer accounts',adminDashboard:'Admin dashboard'};
const singular={subscriptions:'subscription',quotationTemplates:'quotation template',quotations:'quotation',invoices:'invoice',payments:'payment',products:'product',plans:'plan',customers:'customer',discounts:'discount',taxes:'tax rule',team:'staff member'};
let user=null,data={},page='overview',query='',statusFilter='',range=30,accountOpen=false,tab='subscriptions',editing=null,reportCurrency='INR',adminStats=null,adminAudit=[],adminCustomerAccounts=[],notifications=[],notificationUnread=0,notificationOpen=false,outsideClickHandler=null,excelSchema=null,reportDraft={dataset:'subscriptions',title:'Subscriptions report',fields:[],status:'',currency:'',dateFrom:'',dateTo:''};
async function api(path,method='GET',body){const r=await fetch(`/api${path}`,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const result=await r.json();if(!r.ok){if(r.status===401&&user){user=null;auth('login');}throw Error(result.error||'Request failed.');}return result;}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>t.classList.remove('show'),4000);}
function brand(){return '<div class="brand"><span class="wordmark">Brightloop</span><span class="console">Software</span></div>';}
const field=(name,label,type='text',value='',help='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='password'?'maxlength="128"':''} required>${help?`<p class="field-help">${help}</p>`:''}</div>`;
function auth(mode='login',notice=''){
  delete document.body.dataset.portal;
  const toastNode=document.querySelector('#toast');toastNode.classList.remove('show');toastNode.textContent='';
  const content={login:['Welcome back','Sign in to your Brightloop workspace.'],register:['Create a customer account','Set up your account to manage software subscriptions and invoices.'],forgot:['Forgot your password?','Enter your account email. We’ll send you a six-digit verification code.'],'otp-reset':['Check your email','Enter the six-digit code sent to '+otpEmail+'.'],'new-password':['Choose a new password','Your email is verified. Set a new password to sign in.'],reset:['Set a new password','Choose a password you can remember and keep private.']}[mode];
  const passwordHelp='More than 8 characters with uppercase, lowercase and a special character.';
  app.innerHTML=`<main class="auth-shell auth-${mode}"><section class="auth-layout"><aside class="auth-story">${brand()}<div class="auth-story-copy"><span class="auth-kicker">SUBSCRIPTIONS, SIMPLIFIED</span><h1>One account.<br>One clear workspace.</h1></div></aside><div class="auth-panel"><div class="auth-panel-inner"><span class="auth-mode">${mode==='register'?'CUSTOMER REGISTRATION':'ACCOUNT ACCESS'}</span><h2>${content[0]}</h2><p class="auth-subtitle">${content[1]}</p><form class="auth-form" id="authForm">${mode==='register'?field('name','Full name'):''}${['login','register','forgot'].includes(mode)?field('email','Email address','email'):''}${mode==='otp-reset'?`<div class="field"><label for="otp">6-digit code</label><input id="otp" name="otp" type="text" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="123456" required autocomplete="one-time-code"></div>`:''}${mode==='new-password'?field('password','New password','password','',passwordHelp)+field('confirm','Confirm new password','password'):''}${['register','login','reset'].includes(mode)?field('password','Password','password','',mode!=='login'?passwordHelp:''):''}${mode==='reset'?field('confirm','Confirm password','password'):''}${['register','login','reset','new-password'].includes(mode)?'<label class="password-toggle"><input type="checkbox" id="showPassword">Show password</label>':''}${mode==='login'?'<div class="auth-assist"><span>Your role is detected from your email.</span><button type="button" class="link-button" data-auth="forgot">Forgot password?</button></div>':''}<p id="authMessage" role="alert" class="${notice?'error':'error'}">${esc(notice)}</p><button class="auth-submit" id="authSubmit" type="submit">${{login:'Continue to workspace',register:'Create customer account',forgot:'Send OTP','otp-reset':'Verify OTP','new-password':'Save password & sign in',reset:'Update password'}[mode]||'Submit'}<span>→</span></button><div class="auth-switch">${mode==='login'?'<span>New customer?</span><button type="button" class="link-button" data-auth="register">Create an account</button>':'<span>Already have an account?</span><button type="button" class="link-button" data-auth="login">Back to sign in</button>'}</div>${mode==='otp-reset'?'<div class="auth-switch"><button type="button" class="link-button" id="resendOtp">Resend OTP</button><button type="button" class="link-button" data-auth="forgot">Use a different email</button></div>':''}</form></div></div></section></main>`;
  app.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>auth(b.dataset.auth));
  const resend=document.querySelector('#resendOtp');if(resend)resend.onclick=async()=>{resend.disabled=true;try{await api('/auth/otp/send','POST',{email:otpEmail});toast('A new code has been requested. Check your inbox and spam folder.');}catch(error){document.querySelector('#authMessage').textContent=error.message;}finally{resend.disabled=false;}};
  const pw=document.querySelector('#showPassword');if(pw)pw.onchange=()=>app.querySelectorAll('input[name=password],input[name=confirm]').forEach(i=>i.type=pw.checked?'text':'password');
  document.querySelector('#authForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target)),button=document.querySelector('#authSubmit'),msg=document.querySelector('#authMessage');msg.textContent='';button.disabled=true;try{
    if(mode==='reset'){if(b.password!==b.confirm)throw Error('Passwords do not match.');b.token=new URLSearchParams(location.search).get('reset');}
    if(mode==='forgot'){await api('/auth/otp/send','POST',{email:b.email});otpEmail=b.email.trim().toLowerCase();recoveryToken='';auth('otp-reset');return;}
    if(mode==='otp-reset'){const verified=await api('/auth/otp/verify','POST',{email:otpEmail,otp:b.otp});recoveryToken=verified.recoveryToken;auth('new-password');return;}
    if(mode==='new-password'){if(b.password!==b.confirm)throw Error('Passwords do not match.');const result=await api('/auth/otp/reset','POST',{recoveryToken,password:b.password});recoveryToken='';otpEmail='';user=result.user;accountOpen=false;notificationOpen=false;page=admin()?'adminDashboard':'overview';await load();shell();toast('Password updated. You are signed in.');return;}
    const result=await api(`/auth/${mode}`,'POST',b);
    if(mode==='login'){accountOpen=false;notificationOpen=false;user=result.user;history.replaceState(null,'','/');await load();shell();toast(`Signed in to the ${user.role} portal.`);}
    else if(mode==='register'){auth('login');toast('Account created. Sign in to continue.');}
    else if(mode==='reset'){history.replaceState(null,'','/');auth('login');toast('Password updated. Sign in with your new password.');}
    else{msg.className='success';msg.textContent=result.message;}
  }catch(err){msg.className='error';msg.textContent=err.message;}finally{button.disabled=false;}};
}
async function loadNotifications(){try{const result=await api('/notifications');notifications=result.items||[];notificationUnread=Number(result.unread||0);}catch{notifications=[];notificationUnread=0;}}
async function load(){data=await api('/state');await loadNotifications();if(user?.role!=='customer'){excelSchema=await api('/reports/schema');if(!reportDraft.fields.length){const definition=excelSchema.datasets.find(item=>item.key===reportDraft.dataset)||excelSchema.datasets[0];reportDraft={...reportDraft,dataset:definition.key,title:`${definition.label} report`,fields:[...definition.defaults]};}}if(user?.role==='admin'){data.team=await api('/team');try{adminStats=await api(`/admin/stats?currency=${reportCurrency}`);adminAudit=await api('/admin/audit');adminCustomerAccounts=await api('/admin/customers');}catch{adminStats=null;adminAudit=[];adminCustomerAccounts=[];}}}
const admin=()=>user?.role==='admin',staff=()=>user?.role==='staff',customer=()=>user?.role==='customer',internal=()=>!customer();
const portalName=()=>admin()?'Admin control center':staff()?'Staff workspace':'Customer portal';
function nav(name,symbol){return `<button class="nav-item ${page===name?'active':''}" data-page="${name}">${icon(symbol)}<span>${titles[name]}</span></button>`;}
function shell(){
  document.body.dataset.portal=user.role;
  const operations=nav('subscriptions','autorenew')+(customer()?nav('quotations','request_quote'):'')+(internal()?nav('quotations','request_quote')+nav('quotationTemplates','content_copy'):'');
  const billing=`<div class="nav-group">${icon('arrow_drop_down')} Billing</div>${nav('invoices','description')}${nav('payments','account_balance_wallet')}`;
  const adminCatalog=admin()?`<div class="nav-group">${icon('arrow_drop_down')} Catalog</div>${nav('products','inventory_2')}${nav('plans','view_agenda')}${nav('customers','group')}${nav('discounts','sell')}${nav('taxes','percent')}`:'';
  const staffCustomers=staff()?`<div class="nav-group">${icon('arrow_drop_down')} Services</div>${nav('products','inventory_2')}${nav('plans','view_agenda')}${nav('customers','group')}${nav('staffWork','task_alt')}${nav('staffSupport','support_agent')}`:'';
  const customerPlans=customer()?`<div class="nav-group">${icon('arrow_drop_down')} Explore</div>${nav('store','apps')}`:'';
  app.innerHTML=`<header class="topbar"><button class="icon-button" id="menu" aria-label="Toggle navigation">${icon('menu')}</button>${brand()}<div class="search">${icon('search')}<input id="search" placeholder="Search this workspace" aria-label="Search records" value="${esc(query)}"></div><div class="portal-pill ${esc(user.role)}">${esc(user.role)}</div><div class="top-actions"><button class="icon-button optional" id="help" aria-label="Help">${icon('help')}</button><button class="icon-button notification-button" id="notifications" aria-label="Open notifications">${icon('notifications')}${notificationUnread?`<span class="notification-count">${notificationUnread>99?'99+':notificationUnread}</span>`:''}</button><button class="icon-button optional" data-page="profile" aria-label="Account settings">${icon('settings')}</button><button class="avatar" id="account" aria-label="Open account menu">${esc(initials(user.name))}</button></div></header><div class="mobile-overlay" id="overlay"></div><aside class="sidebar"><div class="workspace">${icon(admin()?'admin_panel_settings':staff()?'badge':'person')}<span>${portalName()}</span></div><nav>${admin()?nav('adminDashboard','dashboard'):''}${nav('overview','home')}${operations}${billing}${adminCatalog}${staffCustomers}${customerPlans}<div class="nav-group">${icon('arrow_drop_down')} Account</div>${internal()?nav('reports','monitoring'):''}${nav('profile','account_circle')}${admin()?nav('adminCustomers','person_search'):''}${admin()?nav('team','manage_accounts'):''}</nav><div class="sidebar-note">${esc(user.email)}<br>${esc(portalName())}</div></aside><main class="main" id="main"></main><div id="accountMenu"></div><div id="notificationMenu"></div>`;
  app.querySelector('#menu').onclick=()=>document.body.classList.toggle(innerWidth<=800?'nav-open':'nav-collapsed');
  app.querySelector('#overlay').onclick=()=>document.body.classList.remove('nav-open');
  app.querySelector('#search').oninput=e=>{query=e.target.value;render();};
  app.querySelector('#account').onclick=()=>{accountOpen=!accountOpen;notificationOpen=false;notificationMenu();accountMenu();};
  app.querySelector('#notifications').onclick=()=>{notificationOpen=!notificationOpen;accountOpen=false;accountMenu();notificationMenu();};
  app.querySelector('#help').onclick=()=>toast('Add products and plans, create a customer and subscription, then run billing.');bindNavigation();render();
  if(outsideClickHandler)document.removeEventListener('click',outsideClickHandler);outsideClickHandler=event=>{if(event.target.closest('#account,#accountMenu,#notifications,#notificationMenu'))return;if(accountOpen||notificationOpen){accountOpen=false;notificationOpen=false;accountMenu();notificationMenu();}};document.addEventListener('click',outsideClickHandler);
}
function bindNavigation(){app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;statusFilter='';query='';app.querySelector('#search').value='';document.body.classList.remove('nav-open');accountOpen=false;notificationOpen=false;accountMenu();notificationMenu();app.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));render();});}
function accountMenu(){const node=document.querySelector('#accountMenu');if(!node)return;node.innerHTML=accountOpen?`<section class="account-popover"><p>${esc(user.email)}</p><div class="avatar">${esc(initials(user.name))}</div><h2>Hi, ${esc(user.name.split(' ')[0])}!</h2><p>${esc(user.role)} account</p><button class="outline-button" data-page="profile">Manage your account</button><br><button class="text-button" id="logout">${icon('logout')}Sign out</button></section>`:'';bindNavigation();if(accountOpen)document.querySelector('#logout').onclick=async()=>{await api('/auth/logout','POST');user=null;data={};page='overview';auth();};}
function notificationMenu(){const node=document.querySelector('#notificationMenu');if(!node)return;node.innerHTML=notificationOpen?`<section class="notification-popover"><div class="notification-head"><div><strong>Notifications</strong><small>${notificationUnread?`${notificationUnread} unread`:'All caught up'}</small></div>${notificationUnread?'<button class="text-button" id="markAllNotifications">Mark all read</button>':''}</div><div class="notification-list">${notifications.length?notifications.slice(0,12).map(n=>`<button class="notification-item ${n.readAt?'read':''}" data-notification-id="${esc(n.id)}"><span class="notification-dot"></span><span><strong>${esc(n.title)}</strong><small>${esc(n.message)}</small><time>${esc(new Date(n.createdAt).toLocaleString())}</time></span></button>`).join(''):'<p class="notification-empty">No notifications yet.</p>'}</div></section>`:'';if(!notificationOpen)return;const allButton=document.querySelector('#markAllNotifications');if(allButton)allButton.onclick=async()=>{await api('/notifications/all','POST');await loadNotifications();notificationMenu();render();};document.querySelectorAll('[data-notification-id]').forEach(button=>button.onclick=async()=>{await api(`/notifications/${button.dataset.notificationId}/read`,'POST');await loadNotifications();notificationMenu();render();});}
const lookup=(type,id,key='name')=>data[type]?.find(x=>x.id===id)?.[key]||'—';
const outstanding=i=>Math.max(0,Number(i.total)-data.payments.filter(p=>p.invoiceId===i.id).reduce((s,p)=>s+Number(p.amount),0));
const badge=s=>`<span class="badge ${['Active','Paid','Confirmed'].includes(s)?'green':['Paused','Draft','Quotation'].includes(s)?'amber':['Closed','Cancelled','Overdue','Expired'].includes(s)?'red':'blue'}">${esc(s)}</span>`;
function filtered(type){return (data[type]||[]).filter(r=>(!statusFilter||r.status===statusFilter)&&(!query||JSON.stringify({...r,customer:lookup('customers',r.customerId),plan:lookup('plans',r.planId)}).toLowerCase().includes(query.toLowerCase())));}
function canCreate(){return internal()&&singular[page]&&page!=='invoices'&&(!['products','plans','discounts','taxes','quotationTemplates','team'].includes(page)||admin());}
Object.assign(titles,{staffWork:'Assigned work',staffSupport:'Customer support'});
function render(){const main=document.querySelector('#main');if(!main)return;
  if(customer()){renderCustomerPortal({main,page,user,data,query,api,load,render,esc,icon,toast,printInvoice,navigate:next=>{page=next;query='';app.querySelector('#search').value='';app.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));render();}});bindNavigation();return;}
  if(staff()&&['overview','customers','staffWork','staffSupport','profile'].includes(page)){renderStaffPortal({main,page,user,data,query,api,load,render,esc,icon,toast});bindNavigation();return;}
  main.innerHTML=`<div class="page-heading"><div><h1>${titles[page]||titles.overview}</h1></div><div class="page-heading-actions">${page==='invoices'&&internal()?`<button class="text-button billing-button" id="bill">${icon('autorenew')}Run billing</button>`:''}${canCreate()?`<button class="primary-button" id="create">${icon('add')}Create ${singular[page]}</button>`:''}${['overview','reports','adminDashboard'].includes(page)?`<select id="reportCurrency" aria-label="Report currency">${['INR','USD'].map(c=>`<option ${c===reportCurrency?'selected':''}>${c}</option>`).join('')}</select>`:''}${page==='reports'||page==='overview'||(page==='invoices'&&internal())?`<button class="text-button" id="export">${icon(page==='reports'?'table_view':'download')}${page==='reports'?'CREATE EXCEL':'EXPORT CSV'}</button>`:''}</div></div>${page==='adminDashboard'?adminDashboard():page==='overview'?overview():page==='reports'?reports():page==='profile'?profile():page==='team'?team():page==='adminCustomers'?adminCustomersPage():listPage()}`;
  const currency=document.querySelector('#reportCurrency');if(currency)currency.onchange=async()=>{reportCurrency=currency.value;await load();render();};
  if(page==='team'&&admin()){main.insertAdjacentHTML('beforeend',adminTaskForm(data,esc));bindAdminTaskForm(data,api,toast);}
  const create=document.querySelector('#create');if(create)create.onclick=()=>openEditor(page);
  const billButton=document.querySelector('#bill');if(billButton)billButton.onclick=async()=>{billButton.disabled=true;try{const r=await api('/billing','POST');await refresh();toast(`${r.count} invoices generated. Already billed periods were skipped.`);}catch(e){toast(e.message);}finally{billButton.disabled=false;}};
  const exportButton=document.querySelector('#export');if(exportButton)exportButton.onclick=page==='reports'?()=>document.querySelector('#excelBuilder')?.scrollIntoView({behavior:'smooth',block:'start'}):exportCSV;
  if(page==='reports')bindExcelBuilder();
  const printReport=document.querySelector('#printReport');if(printReport)printReport.onclick=()=>window.print();
  document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(page,data[page].find(r=>r.id===b.dataset.edit)));
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});
  const status=document.querySelector('#status');if(status)status.onchange=e=>{statusFilter=e.target.value;render();};
  const period=document.querySelector('#period');if(period)period.onchange=e=>{range=Number(e.target.value);render();};
  if(page==='profile')document.querySelector('#profileForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/profile','POST',Object.fromEntries(new FormData(e.target)));user=r.user;shell();toast('Profile updated.');}catch(err){toast(err.message);}};
  document.querySelectorAll('[data-staff-action]').forEach(b=>b.onclick=async()=>{const id=b.dataset.staffId,action=b.dataset.staffAction;try{if(action==='edit'){const member=(data.team||[]).find(m=>m.id===id);if(!member)return;openStaffEditor(member);return;}if(action==='deactivate'&&!confirm('Deactivate this staff account? They will be signed out and unable to log in.'))return;if(action==='reset'){const pw=prompt('Enter a temporary password with more than 8 characters, uppercase, lowercase and a special character.');if(!pw)return;await api(`/staff/${id}/reset`,'POST',{password:pw});await refresh();toast('Password has been reset.');return;}await api(`/staff/${id}/${action}`,'POST');await refresh();toast(action==='deactivate'?'Account deactivated.':'Account reactivated.');}catch(e){toast(e.message);}});
  document.querySelectorAll('[data-cust-action]').forEach(b=>b.onclick=async()=>{const id=b.dataset.custId,action=b.dataset.custAction;try{if(action==='deactivate'&&!confirm('Deactivate this customer account? They will be signed out and unable to log in.'))return;if(action==='reset'){const pw=prompt('Enter a temporary password with more than 8 characters, uppercase, lowercase and a special character.');if(!pw)return;await api(`/users/${id}/reset`,'POST',{password:pw});await refresh();toast('Password has been reset.');return;}if(action==='link'){await api(`/admin/customers/${id}/link`,'POST',{customerId:b.dataset.billingId});await refresh();toast('Billing record linked to the customer account.');return;}await api(`/users/${id}/${action}`,'POST');await refresh();toast(action==='deactivate'?'Customer account deactivated.':'Customer account reactivated.');}catch(e){toast(e.message);}});
  bindNavigation();
}
async function refresh(){await load();render();}
const recordAmount=record=>(record.lines?.length?record.lines.reduce((sum,line)=>sum+Number(line.unitPrice||0)*Number(line.quantity||0),0):Number(record.unitPrice||0)*Number(record.quantity||1));
function metrics(){const active=data.subscriptions.filter(s=>s.status==='Active'&&(s.currency||'USD')===reportCurrency);const mrr=active.reduce((sum,s)=>sum+recordAmount(s)*({Daily:30.4375,Weekly:52/12,Monthly:1,Yearly:1/12}[s.cycle]||1),0);const cutoff=new Date(Date.now()-range*86400000).toISOString().slice(0,10);const collected=data.payments.filter(p=>p.date>=cutoff&&(data.invoices.find(i=>i.id===p.invoiceId)?.currency||'INR')===reportCurrency).reduce((s,p)=>s+Number(p.amount),0);const owed=data.invoices.filter(i=>['Confirmed','Paid'].includes(i.status)&&(i.currency||'USD')===reportCurrency).reduce((s,i)=>s+outstanding(i),0);return {active:active.length,mrr,collected,owed};}
function overview(){const m=metrics();const welcome=admin()?['Workspace command center','Manage access, pricing, subscriptions and financial activity across the business.']:staff()?['Today’s operations','Create customers and quotations, manage subscriptions, and keep invoices moving.']:[`Welcome, ${user.name.split(' ')[0]}`,'Review your subscriptions, invoices and payment history from one private place.'];return `<section class="portal-welcome"><div><h2>${esc(welcome[0])}</h2><p>${esc(welcome[1])}</p></div><div class="welcome-role-icon">${icon(admin()?'shield_person':staff()?'work':'person')}</div></section><div class="filter-row"><span class="chip">${internal()?'Workspace: All customers':'Account: My records'} ${icon('edit')}</span><select id="period" aria-label="Date range"><option value="30" ${range===30?'selected':''}>Date: Last 30 days</option><option value="90" ${range===90?'selected':''}>Date: Last 90 days</option><option value="365" ${range===365?'selected':''}>Date: Last year</option></select><span class="updated">Last updated: just now</span></div><section class="panel"><div class="metrics"><article class="metric selected-blue"><div class="metric-label">${icon('check_box')}${customer()?'My recurring total':'Monthly recurring revenue'}</div><strong>${money(m.mrr)}</strong><small>Active plans, normalized to one month</small></article><article class="metric selected-purple"><div class="metric-label">${icon('check_box')}Active subscriptions</div><strong>${m.active}</strong><small>Currently active customer contracts</small></article><article class="metric"><div class="metric-label">${icon('check_box_outline_blank')}${customer()?'Payments made':'Payments collected'}</div><strong>${money(m.collected)}</strong><small>Within the selected date range</small></article><article class="metric"><div class="metric-label">${icon('check_box_outline_blank')}Outstanding balance</div><strong>${money(m.owed)}</strong><small>All unpaid invoice balances</small></article></div>${chart()}</section><section class="panel"><div class="tabs">${['subscriptions','invoices','payments'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${titles[t]}</button>`).join('')}</div><div class="table-tools"><span>${filtered(tab).length} records</span><button class="text-button" data-page="${tab}">View all ${icon('arrow_forward')}</button></div>${table(tab,filtered(tab).slice(0,6),false)}</section>`;}
function chart(){const start=new Date();start.setUTCHours(0,0,0,0);start.setUTCDate(start.getUTCDate()-range+1);const bins=Array.from({length:12},(_,i)=>{const from=new Date(start.getTime()+i*range/12*86400000).toISOString().slice(0,10);const to=new Date(start.getTime()+(i+1)*range/12*86400000).toISOString().slice(0,10);return {from,payments:data.payments.filter(p=>p.date>=from&&p.date<to&&(data.invoices.find(i=>i.id===p.invoiceId)?.currency||'INR')===reportCurrency).reduce((s,p)=>s+Number(p.amount),0),invoices:data.invoices.filter(p=>p.billingDate>=from&&p.billingDate<to&&['Confirmed','Paid'].includes(p.status)&&(p.currency||'USD')===reportCurrency).reduce((s,p)=>s+Number(p.total),0)};});const max=Math.max(100,...bins.flatMap(b=>[b.payments,b.invoices]))*1.15;const points=key=>bins.map((b,i)=>`${i*760/11},${220-b[key]/max*200}`).join(' ');return `<div class="chart"><div class="chart-labels"><span>Revenue (${reportCurrency})</span><span>${data.payments.length||data.invoices.length?'Actual billing & collections':'Your billing activity will appear here'}</span></div><div class="plot"><svg viewBox="0 0 760 250" preserveAspectRatio="none" role="img" aria-label="Actual invoiced and collected revenue over the selected period">${[0,1,2,3,4].map(i=>`<line class="grid-line" x1="0" x2="760" y1="${20+i*50}" y2="${20+i*50}"/><text class="axis-label" x="-10" y="${24+i*50}" text-anchor="end">${Math.round(max*(4-i)/4)}</text>`).join('')}<polyline class="chart-line" stroke="#4285f4" points="${points('payments')}"/><polyline class="chart-line" stroke="#673ab7" points="${points('invoices')}"/>${bins.filter((_,i)=>i%3===0||i===11).map(b=>`<text class="axis-label" x="${bins.indexOf(b)*760/11}" y="246" text-anchor="${bins.indexOf(b)===0?'start':bins.indexOf(b)===11?'end':'middle'}">${esc(b.from.slice(5))}</text>`).join('')}</svg></div><div class="chart-legend"><span><i class="dot" style="background:#4285f4"></i>Collected payments</span><span><i class="dot" style="background:#673ab7"></i>Invoiced revenue</span></div></div>`;}
const columns={products:['Product','Type','Sales price','Cost price','Notes'],plans:['Plan','Product','Price / cycle','Minimum quantity','Availability'],customers:['Customer','Email','Company'],quotationTemplates:['Template','Product lines','Validity','Payment terms'],subscriptions:['Subscription','Customer','Products','Plan','Quantity','Price / cycle','Next billing','Status'],quotations:['Quotation','Customer','Products','Plan','Amount','Valid until','Status'],invoices:['Invoice','Customer','Total','Balance','Due date','Status'],payments:['Invoice','Amount','Method','Date','Notes'],discounts:['Discount','Type','Value','Scope / eligibility','Validity','Uses'],taxes:['Tax rule','Rate']};
function cells(type,r){const lineNames=record=>(record.lines?.length?record.lines:[record]).map(line=>lookup('products',line.productId)+(line.variantName?` · ${line.variantName}`:'')).join(', ');switch(type){case'products':return [esc(r.name),esc(r.productType||'—'),money(r.price,r.currency||'INR'),r.cost==null?'Not set':money(r.cost,r.currency||'INR'),esc(r.notes||'—')];case'plans':return [esc(r.name),esc(lookup('products',r.productId)),r.price==null||r.price===''?'Not set':`${money(r.price,r.currency||'INR')} / ${esc(r.cycle)}`,esc(r.minQuantity),`${esc(r.starts||'Anytime')} → ${esc(r.ends||'No end date')}${r.autoClose?'<small>Auto-close enabled</small>':''}`];case'customers':return [`<div class="cell-person"><div class="cell-avatar">${esc(initials(r.name))}</div><strong>${esc(r.name)}</strong></div>`,esc(r.email),esc(r.company||'—')];case'quotationTemplates':return [esc(r.name),`${esc(lineNames(r))}<small>${r.lines?.length||1} line(s)</small>`,`${esc(r.validDays)} days`,esc(r.terms||'Net 15')];case'subscriptions':return [esc(r.number),esc(lookup('customers',r.customerId)),`${esc(lineNames(r))}<small>${r.lines?.length||1} line(s)</small>`,`${esc(lookup('plans',r.planId))}<small>${esc(r.cycle||'Monthly')}</small>`,esc((r.lines||[r]).reduce((n,line)=>n+Number(line.quantity||0),0)),money(recordAmount(r),r.currency||'INR'),esc(r.nextBilling||r.starts),badge(r.status)];case'quotations':return [esc(r.number),esc(lookup('customers',r.customerId)),`${esc(lineNames(r))}<small>${r.lines?.length||1} line(s)</small>`,esc(lookup('plans',r.planId)),money(recordAmount(r),r.currency||'INR'),esc(r.ends||'—'),badge(r.status||'Draft')];case'invoices':return [esc(r.number),esc(lookup('customers',r.customerId)),money(r.total,r.currency||'INR'),money(outstanding(r),r.currency||'INR'),esc(r.due),badge(r.status!=='Paid'&&r.status!=='Cancelled'&&r.due<today()?'Overdue':r.status)];case'payments':return [esc(lookup('invoices',r.invoiceId,'number')),money(r.amount,data.invoices.find(i=>i.id===r.invoiceId)?.currency||'INR'),esc(r.method),esc(r.date),esc(r.notes||'—')];case'discounts':return [esc(r.name),esc(r.kind),r.kind==='Percentage'?`${esc(r.value)}%`:money(r.value),`${esc(r.scope||'Subscription')}<small>${r.productId?esc(lookup('products',r.productId)):''} · min ${money(r.minPurchase||0)}</small>`,`${esc(r.starts||'Anytime')} → ${esc(r.ends||'No end date')}`,`${r.used||0} / ${esc(r.limit||'Unlimited')}`];case'taxes':return [esc(r.name),`${esc(r.rate)}%`];}}
function table(type,rows,actions=true){const label=(titles[type]||type).toLowerCase();if(!rows.length)return `<div class="empty">${icon('folder_open')}<h2>${query||statusFilter?'No matching records':`No ${label} yet`}</h2><p>${query||statusFilter?'Try a different search or status filter.':type==='invoices'?'Activate a subscription, then run billing to generate its invoices.':`Your ${label} will appear here when they are created.`}</p></div>`;const hasActions=actions&&(internal()||type==='invoices');return `<div class="table-scroll"><table><thead><tr>${columns[type].filter(c=>!(staff()&&c==='Cost price')).map(c=>`<th>${c}</th>`).join('')}${hasActions?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${cells(type,r).filter((c,i)=>!(staff()&&type==='products'&&i===3)).map(c=>`<td>${c}</td>`).join('')}${hasActions?`<td><div class="row-actions">${rowActions(type,r)}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function rowActions(type,r){const a=(action,label)=>`<button class="text-button" data-action="${action}" data-id="${r.id}">${label}</button>`;if(type==='invoices')return a('print','Print')+(internal()?(r.status==='Draft'?a('confirmInvoice','Confirm')+a('cancel','Cancel'):['Confirmed','Paid'].includes(r.status)?a('send','Email')+(r.status==='Confirmed'?a('pay','Record payment')+a('cancel','Cancel'):''):''):'');if(type==='payments')return '';if(type==='quotations')return `<button class="text-button" data-edit="${r.id}">Edit</button>`+(['Draft','Quotation'].includes(r.status)?a('convert','Convert'):'');if(type==='subscriptions'){const edit=`<button class="text-button" data-edit="${r.id}">Edit</button>`;if(r.status==='Draft')return edit+a('quote','Prepare quotation')+a('close','Close');if(r.status==='Quotation')return edit+a('confirm','Confirm')+a('close','Close');if(r.status==='Confirmed')return edit+a('activate','Activate')+a('close','Close');if(r.status==='Active')return edit+a('pause','Pause')+a('close','Close');if(r.status==='Paused')return edit+a('resume','Resume')+a('close','Close');if(r.status==='Closed')return edit+a('renew','Renew');return edit;}return (!['products','plans','discounts','taxes','quotationTemplates'].includes(type)||admin())?`<button class="text-button" data-edit="${r.id}">Edit</button>`+a('delete','Delete'):'';}
function listPage(){const statuses=[...new Set((data[page]||[]).map(r=>r.status).filter(Boolean))];return `${page==='subscriptions'&&internal()?'<div class="banner">Billing runs automatically every minute while the server is running. Only active subscriptions generate invoices; each billing period is charged once.</div>':page==='customers'?'<div class="banner">Saving a customer links their portal to an existing registered account with the same email. Confirm the account owner before linking billing records.</div>':''}<div class="filter-row"><span class="chip">${internal()?'All records':'My records'}</span>${statuses.length?`<select id="status" aria-label="Filter by status"><option value="">All statuses</option>${statuses.map(s=>`<option ${statusFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}<span class="updated">${filtered(page).length} records</span></div><section class="panel"><div class="panel-head"><h2>${titles[page]}</h2><span class="muted">${internal()?'Workspace records':'Your account'}</span></div>${table(page,filtered(page))}</section>`;}
function reports(){const m=metrics();const overdue=data.invoices.filter(i=>i.status!=='Paid'&&['Confirmed','Paid'].includes(i.status)&&i.due<today()&&(i.currency||'USD')===reportCurrency);return `${excelBuilder()}<div class="summary-grid"><section class="panel"><h3>Monthly recurring revenue</h3><strong>${money(m.mrr)}</strong><span class="muted">Before discounts and taxes</span></section><section class="panel"><h3>Collections · last ${range} days</h3><strong>${money(m.collected)}</strong><span class="muted">Recorded payments</span></section><section class="panel"><h3>Overdue invoices</h3><strong>${overdue.length}</strong><span class="muted">${money(overdue.reduce((s,i)=>s+outstanding(i),0))} outstanding</span></section></div><section class="panel"><div class="panel-head"><h2>Revenue & collections</h2><button class="text-button" id="printReport">Print report</button></div>${chart()}</section><section class="panel"><div class="panel-head"><h2>Overdue invoices</h2></div>${table('invoices',overdue,false)}</section>`;}

function excelBuilder(){
  const definitions=excelSchema?.datasets||[],definition=definitions.find(item=>item.key===reportDraft.dataset)||definitions[0];
  if(!definition)return '<section class="panel report-builder"><div class="empty"><h2>Report builder unavailable</h2><p>Reload the page and try again.</p></div></section>';
  const selected=reportDraft.fields.length?reportDraft.fields:definition.defaults;
  const dateTypes=!['customers'].includes(definition.key);
  const source=definition.key==='renewals'?data.subscriptions:(data[definition.key]||[]);
  let preview=source.filter(item=>(!reportDraft.status||item.status===reportDraft.status)&&(!reportDraft.currency||(item.currency||'INR')===reportDraft.currency));
  const dateKey={subscriptions:'starts',renewals:'nextBilling',invoices:'billingDate',payments:'date',quotations:'starts'}[definition.key];
  if(dateKey&&reportDraft.dateFrom)preview=preview.filter(item=>item[dateKey]>=reportDraft.dateFrom);
  if(dateKey&&reportDraft.dateTo)preview=preview.filter(item=>item[dateKey]<=reportDraft.dateTo);
  return `<section class="panel report-builder" id="excelBuilder"><div class="report-builder-head"><div><span>EXCEL REPORT BUILDER</span><h2>Create a spreadsheet</h2><p>Choose the records and columns. Brightloop will prepare a formatted Excel file from the current database.</p></div><div class="excel-file-icon">${icon('table_view')}<small>.XLSX</small></div></div><div class="report-builder-grid"><form id="excelReportForm" class="report-form"><div class="report-question"><label for="reportTitle">Report title</label><input id="reportTitle" name="title" maxlength="80" required value="${esc(reportDraft.title)}"><small>Appears at the top of the Excel sheet.</small></div><div class="report-question"><label for="reportDataset">What should this sheet contain?</label><select id="reportDataset" name="dataset">${definitions.map(item=>`<option value="${esc(item.key)}" ${item.key===definition.key?'selected':''}>${esc(item.label)}</option>`).join('')}</select></div><fieldset class="report-question"><legend>Columns to include</legend><div class="report-field-grid">${definition.fields.map(item=>`<label class="report-checkbox"><input type="checkbox" name="fields" value="${esc(item.key)}" ${selected.includes(item.key)?'checked':''}><span>${esc(item.label)}</span></label>`).join('')}</div><small>Select at least one column.</small></fieldset><div class="report-filter-grid">${definition.statuses.length?`<div class="report-question"><label for="reportStatus">Status</label><select id="reportStatus" name="status"><option value="">All statuses</option>${definition.statuses.map(value=>`<option ${value===reportDraft.status?'selected':''}>${esc(value)}</option>`).join('')}</select></div>`:''}${definition.currencies.length?`<div class="report-question"><label for="reportFileCurrency">Currency</label><select id="reportFileCurrency" name="currency"><option value="">All currencies</option>${definition.currencies.map(value=>`<option ${value===reportDraft.currency?'selected':''}>${esc(value)}</option>`).join('')}</select></div>`:''}${dateTypes?`<div class="report-question"><label for="reportDateFrom">From date</label><input id="reportDateFrom" name="dateFrom" type="date" value="${esc(reportDraft.dateFrom)}"></div><div class="report-question"><label for="reportDateTo">To date</label><input id="reportDateTo" name="dateTo" type="date" value="${esc(reportDraft.dateTo)}"></div>`:''}</div><p class="error" id="excelReportError" role="alert"></p><button class="primary-button" id="createExcel" type="submit">${icon('download')}Create Excel file</button></form><aside class="report-preview"><span>FILE PREVIEW</span><h3>${esc(reportDraft.title||`${definition.label} report`)}</h3><div class="preview-sheet"><div class="preview-sheet-head"><strong>${esc(definition.label)}</strong><small>${preview.length} matching record${preview.length===1?'':'s'}</small></div><div class="preview-columns">${selected.map(key=>definition.fields.find(item=>item.key===key)?.label).filter(Boolean).map(label=>`<span>${esc(label)}</span>`).join('')||'<em>Choose columns to continue</em>'}</div></div><p>${selected.length} column${selected.length===1?'':'s'} selected. The downloaded sheet includes filters, frozen headers, typed dates and numeric amounts.</p></aside></div></section>`;
}

function bindExcelBuilder(){
  const form=document.querySelector('#excelReportForm');if(!form)return;
  const remember=()=>{const values=new FormData(form);reportDraft={dataset:String(values.get('dataset')||reportDraft.dataset),title:String(values.get('title')||''),fields:values.getAll('fields').map(String),status:String(values.get('status')||''),currency:String(values.get('currency')||''),dateFrom:String(values.get('dateFrom')||''),dateTo:String(values.get('dateTo')||'')};};
  document.querySelector('#reportDataset').onchange=e=>{const next=excelSchema.datasets.find(item=>item.key===e.target.value);reportDraft={dataset:next.key,title:`${next.label} report`,fields:[...next.defaults],status:'',currency:'',dateFrom:'',dateTo:''};render();};
  form.querySelectorAll('input,select').forEach(control=>{if(control.id==='reportDataset')return;control.onchange=()=>{remember();render();};});
  form.onsubmit=async event=>{event.preventDefault();remember();const button=document.querySelector('#createExcel'),error=document.querySelector('#excelReportError');error.textContent='';if(!reportDraft.fields.length){error.textContent='Select at least one column.';return;}button.disabled=true;try{const response=await fetch('/api/reports/xlsx',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(reportDraft)});if(!response.ok){const result=await response.json();throw Error(result.error||'The Excel file could not be created.');}const blob=await response.blob(),disposition=response.headers.get('content-disposition')||'',name=disposition.match(/filename="([^"]+)"/)?.[1]||'brightloop-report.xlsx',url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Excel report created with ${response.headers.get('x-report-count')||0} records.`);}catch(err){error.textContent=err.message;}finally{button.disabled=false;}};
}
function profile(){return `<section class="panel profile-card"><div class="avatar">${esc(initials(user.name))}</div><h2>Personal information</h2><form id="profileForm">${field('name','Full name','text',user.name)}<div class="field"><label>Email address</label><input type="email" value="${esc(user.email)}" disabled><p class="field-help">Your sign-in email</p></div><div class="field"><label>Account role</label><input value="${esc(user.role)}" disabled></div><button class="primary-button">Save changes</button></form><p class="muted" style="margin-top:28px">To change your password, sign out and choose “Forgot password?” on the sign-in page.</p></section>`;}
function team(){const activeTeam=(data.team||[]).filter(m=>!query||JSON.stringify(m).toLowerCase().includes(query.toLowerCase()));return `<div class="banner">Staff can manage customers and billing. Only administrators can change the catalog, tax rules and discounts. Deactivated accounts cannot sign in.</div><section class="panel"><div class="panel-head"><h2>Workspace members</h2><span class="muted">${activeTeam.length} members</span></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${activeTeam.map(m=>`<tr><td><div class="cell-person"><div class="cell-avatar">${esc(initials(m.name))}</div><strong>${esc(m.name)}</strong></div></td><td>${esc(m.email)}</td><td>${badge(m.role)}</td><td>${badge(m.status||'active')}</td><td><div class="row-actions">${m.id!==user.id?`<button class="text-button" data-staff-action="edit" data-staff-id="${m.id}">Edit</button>${(m.status||'active')==='active'?`<button class="text-button" data-staff-action="deactivate" data-staff-id="${m.id}">Deactivate</button>`:`<button class="text-button" data-staff-action="activate" data-staff-id="${m.id}">Activate</button>`}<button class="text-button" data-staff-action="reset" data-staff-id="${m.id}">Reset password</button>`:'<span class="muted">You</span>'}</div></td></tr>`).join('')}</tbody></table></div></section>`;}
function openStaffEditor(member){editing={type:'staffEdit',id:member?.id};document.querySelector('#dialogTitle').textContent=member?'Edit staff member':'Create staff member';document.querySelector('#formError').textContent='';
  if(member){document.querySelector('#formFields').innerHTML=`<div class="field"><label for="edit-name">Full name</label><input id="edit-name" name="name" type="text" value="${esc(member.name)}" required></div><div class="field"><label for="edit-email">Email address</label><input id="edit-email" name="email" type="email" value="${esc(member.email)}" required></div>`;
  }else{document.querySelector('#formFields').innerHTML=schema.team.map(([name,label,type='text'])=>`<div class="field"><label for="edit-${name}">${label}</label><input id="edit-${name}" name="${name}" type="${type}" required></div>`).join('');}
  if(!dialog.open)dialog.showModal();}
function adminDashboard(){const s=adminStats||{};const todayStr=new Date().toLocaleDateString('en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric'});return `<section class="portal-welcome admin-welcome"><div><h2>Business Overview</h2><p>${todayStr}</p></div><div class="welcome-role-icon">${icon('shield_person')}</div></section><div class="admin-stats-grid"><div class="admin-stat-card stat-revenue"><div class="stat-icon">${icon('payments')}</div><div><div class="stat-label">Total Revenue</div><div class="stat-value">${money(s.totalRevenue||0)}</div><div class="stat-sub">All time collected</div></div></div><div class="admin-stat-card stat-mrr"><div class="stat-icon">${icon('trending_up')}</div><div><div class="stat-label">Monthly Recurring Revenue</div><div class="stat-value">${money(s.mrr||0)}</div><div class="stat-sub">${s.activeSubscriptions||0} active subscriptions</div></div></div><div class="admin-stat-card stat-outstanding"><div class="stat-icon">${icon('account_balance')}</div><div><div class="stat-label">Outstanding Balance</div><div class="stat-value">${money(s.owed||0)}</div><div class="stat-sub">${s.overdueInvoices||0} overdue invoices</div></div></div><div class="admin-stat-card stat-customers"><div class="stat-icon">${icon('group')}</div><div><div class="stat-label">Customers</div><div class="stat-value">${s.totalCustomers||0}</div><div class="stat-sub">${s.staffCount||0} staff members</div></div></div></div><div class="admin-detail-row"><section class="panel admin-detail-panel"><div class="panel-head"><h2>Subscription Summary</h2></div><div class="admin-summary-list"><div class="summary-item"><span>Active</span><strong>${s.activeSubscriptions||0}</strong></div><div class="summary-item"><span>Total</span><strong>${s.totalSubscriptions||0}</strong></div><div class="summary-item"><span>Products</span><strong>${s.productCount||0}</strong></div><div class="summary-item"><span>Plans</span><strong>${s.planCount||0}</strong></div></div></section><section class="panel admin-detail-panel"><div class="panel-head"><h2>Billing Summary</h2></div><div class="admin-summary-list"><div class="summary-item"><span>Total Invoices</span><strong>${s.totalInvoices||0}</strong></div><div class="summary-item"><span>Paid</span><strong>${s.paidInvoices||0}</strong></div><div class="summary-item"><span>Overdue</span><strong class="overdue-text">${s.overdueInvoices||0}</strong></div><div class="summary-item"><span>Payments</span><strong>${s.totalPayments||0}</strong></div></div></section></div>${chart()}<section class="panel"><div class="panel-head"><h2>Recent Activity</h2><span class="muted">Last 50 actions</span></div><div class="table-scroll"><table><thead><tr><th>Time</th><th>User</th><th>Action</th></tr></thead><tbody>${(adminAudit||[]).slice(0,15).map(a=>`<tr><td>${esc(new Date(a.time).toLocaleString())}</td><td>${esc(a.userName||'system')}</td><td>${esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="3" class="muted" style="text-align:center;padding:30px">No recent activity</td></tr>'}</tbody></table></div></section>`;}
function adminCustomersPage(){const filtered=adminCustomerAccounts.filter(c=>!query||JSON.stringify(c).toLowerCase().includes(query.toLowerCase()));return `<div class="banner">Link an existing billing record only when its email matches the registered account. This avoids duplicate customer records while protecting existing contracts.</div><section class="panel"><div class="panel-head"><h2>Customer Accounts</h2><span class="muted">${filtered.length} registered accounts</span></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Billing record</th><th>Status</th><th>Actions</th></tr></thead><tbody>${filtered.map(c=>{const linked=data.customers.find(record=>record.userId===c.id),candidate=data.customers.find(record=>record.email?.toLowerCase()===c.email.toLowerCase()&&!record.userId);return `<tr><td><div class="cell-person"><div class="cell-avatar">${esc(initials(c.name))}</div><strong>${esc(c.name)}</strong></div></td><td>${esc(c.email)}</td><td>${linked?badge('Linked'):candidate?`<button class="text-button" data-cust-action="link" data-cust-id="${c.id}" data-billing-id="${candidate.id}">Link matching record</button>`:'<span class="muted">No match</span>'}</td><td>${badge(c.status||'active')}</td><td><div class="row-actions"><button class="text-button" data-cust-action="${(c.status||'active')==='active'?'deactivate':'activate'}" data-cust-id="${c.id}">${(c.status||'active')==='active'?'Deactivate':'Activate'}</button><button class="text-button" data-cust-action="reset" data-cust-id="${c.id}">Reset password</button></div></td></tr>`;}).join('')||'<tr><td colspan="5" class="muted" style="text-align:center;padding:30px">No customer accounts registered yet</td></tr>'}</tbody></table></div></section>`;}
const lineFields=[['productId','Product','@products'],['planId','Plan','@plans'],['quantity','Quantity','number'],['unitPrice','Unit price','number'],['taxId','Tax rule','@taxes',false]];
const schema={products:[['name','Product name'],['productType','Product type',['Software','Service','Add-on']],['currency','Currency',['INR','USD']],['price','Sales price','number'],['cost','Cost price (optional)','number',false],['notes','Variant / notes']],plans:[['name','Plan name'],['productId','Product','@products',false],['price','Price per billing cycle','number',false],['currency','Currency',['INR','USD'],false],['variantMultiplier','Variant price multiplier','number',false],['allowPause','Allow customer pause',['true','false'],false],['allowClose','Allow customer closure',['true','false'],false],['allowRenew','Allow customer renewal',['true','false'],false],['autoClose','Close subscriptions automatically at expiry',['true','false'],false],['cycle','Billing cycle',['Daily','Weekly','Monthly','Yearly']],['minQuantity','Minimum quantity','number'],['starts','Available from','date',false],['ends','Available until','date',false]],customers:[['name','Customer name'],['email','Email address','email'],['company','Company','text',false]],quotationTemplates:[['name','Template name'],...lineFields,['validDays','Valid for (days)','number'],['discountId','Discount','@discounts',false],['terms','Payment terms','text',false]],subscriptions:[['customerId','Customer','@customers'],...lineFields,['starts','Start date','date'],['ends','Expiry date','date',false],['status','Status',['Draft','Quotation','Confirmed','Active','Paused','Closed']],['discountId','Discount','@discounts',false],['terms','Payment terms','text',false]],quotations:[['templateId','Start from template','@quotationTemplates',false],['customerId','Customer','@customers'],...lineFields,['starts','Start date','date'],['ends','Valid until','date'],['status','Status',['Draft','Quotation'],false],['discountId','Discount','@discounts',false],['terms','Payment terms','text',false]],payments:[['invoiceId','Invoice','@invoices'],['amount','Amount','number'],['method','Payment method',['Bank transfer','Card','Cash','Other']],['date','Payment date','date'],['notes','Notes','text',false]],discounts:[['name','Discount name'],['kind','Discount type',['Percentage','Fixed']],['value','Value','number'],['scope','Applies to',['Subscription','Product']],['productId','Specific product','@products',false],['minQuantity','Minimum quantity','number'],['minPurchase','Minimum purchase amount','number',false],['starts','Starts on','date',false],['ends','Expires on','date',false],['limit','Usage limit','number',false]],taxes:[['name','Tax name'],['rate','Tax rate (%)','number']],team:[['name','Full name'],['email','Email address','email'],['password','Temporary password','password']]};
function openEditor(type,record={},preset={}){editing={type,id:record.id};const values={quantity:1,minQuantity:1,minPurchase:0,validDays:30,scope:'Subscription',price:0,cost:0,unitPrice:0,value:0,rate:0,starts:today(),date:today(),status:'Draft',terms:'Net 15',...record,...preset};document.querySelector('#dialogTitle').textContent=`${record.id?'Edit':'Create'} ${singular[type]}`;document.querySelector('#formError').textContent='';
  document.querySelector('#formFields').innerHTML=schema[type].map(([name,label,kind='text',required=true])=>{let input;if(Array.isArray(kind)||kind.startsWith('@')){const options=Array.isArray(kind)?kind.map(v=>[v,v]):(data[kind.slice(1)]||[]).filter(r=>type!=='payments'||r.status==='Confirmed').map(r=>{let label=r.name||`${r.number} · ${money(outstanding(r))}`;if(kind==='@taxes'&&r.rate!=null)label=`${r.name} (${r.rate}%)`;if(kind==='@discounts')label=`${r.name} (${r.kind==='Percentage'?r.value+'%':money(r.value)} off)`;return [r.id,label];});input=`<select id="edit-${name}" name="${name}" ${required?'required':''}><option value="">${required?'Choose…':'None'}</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(values[name])===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}else input=`<input id="edit-${name}" name="${name}" type="${kind}" value="${esc(values[name]??'')}" ${kind==='number'?'min="0" step="0.01"':''} ${required?'required':''}>`;return `<div class="field"><label for="edit-${name}">${label}</label>${input}</div>`;}).join('');
  if(type==='customers'&&admin()){const el=document.createElement('div');el.className='field';el.innerHTML=`<label>Assigned staff<select name="assignedStaffId"><option value="">Unassigned</option>${(data.team||[]).filter(m=>m.role==='staff'&&m.status==='active').map(m=>`<option value="${esc(m.id)}" ${record.assignedStaffId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`;document.querySelector('#formFields').append(el);}
  if(type==='products')productVariantEditor(record.variants||[{id:'standard',name:'Standard',extraPrice:0}]);
  if(['subscriptions','quotations','quotationTemplates'].includes(type))recordLineEditor((record.lines||[]).slice(1));
  const product=document.querySelector('#edit-productId');if(product)product.onchange=()=>{document.querySelector('#edit-unitPrice').value=data.products.find(p=>p.id===product.value)?.price||0;};
  const plan=document.querySelector('#edit-planId');if(plan)plan.onchange=()=>{const selected=data.plans.find(p=>p.id===plan.value);if(selected){if(product)product.value=selected.productId||product.value;document.querySelector('#edit-unitPrice').value=selected.price??data.products.find(p=>p.id===selected.productId)?.price??0;}};
  const template=document.querySelector('#edit-templateId');if(template)template.onchange=()=>applyQuotationTemplate(data.quotationTemplates.find(t=>t.id===template.value));
  if(!dialog.open)dialog.showModal();
}
document.querySelector('#closeDialog').onclick=document.querySelector('#cancelDialog').onclick=()=>dialog.close();
document.querySelector('#recordForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target)),{type,id}=editing,button=e.target.querySelector('button[type=submit]');button.disabled=true;try{if(type==='staffEdit'){await api(`/staff/${id}`,'POST',b);dialog.close();await refresh();toast('Staff member updated.');return;}if(type==='products')b.variants=[...document.querySelectorAll('.variant-row')].map(row=>({id:row.dataset.variantId||undefined,name:row.querySelector('[data-variant-name]').value,extraPrice:row.querySelector('[data-variant-price]').value}));if(['subscriptions','quotations','quotationTemplates'].includes(type)){const pl=data.plans.find(p=>p.id===b.planId);if(!b.productId&&pl?.productId)b.productId=pl.productId;if(pl){b.cycle=pl.cycle;b.currency=pl.currency||'INR';}b.lines=[{productId:b.productId,planId:b.planId,quantity:b.quantity,unitPrice:b.unitPrice,taxId:b.taxId||''},...[...document.querySelectorAll('.billing-line-row')].map(row=>({productId:row.querySelector('[data-line-product]').value,planId:row.querySelector('[data-line-plan]').value,quantity:row.querySelector('[data-line-quantity]').value,unitPrice:row.querySelector('[data-line-price]').value,taxId:row.querySelector('[data-line-tax]').value}))];if(type!=='quotationTemplates'&&!id){b.number=`${type==='subscriptions'?'SUB':'QUO'}-${Date.now().toString(36).toUpperCase()}`;b.status||='Draft';}if(type==='quotationTemplates'){delete b.templateId;delete b.status;}}await api(type==='team'?'/staff':`/records/${type}${id?'/'+id:''}`,id?'PATCH':'POST',b);dialog.close();await refresh();toast(`${singular[type]} saved.`);}catch(err){document.querySelector('#formError').textContent=err.message;}finally{button.disabled=false;}};
async function action(action,id){try{const r=data[page]?.find(x=>x.id===id);if(action==='delete'){if(!confirm('Delete this record? Records used by other items cannot be deleted.'))return;await api(`/records/${page}/${id}`,'DELETE');}else if(['activate','quote','confirm','resume','pause','close'].includes(action)){const targetStatus={activate:'Active',quote:'Quotation',confirm:'Confirmed',resume:'Active',pause:'Paused',close:'Closed'}[action];await api(`/records/subscriptions/${id}`,'PATCH',{status:targetStatus});}else if(action==='pay'){openEditor('payments',{}, {invoiceId:id,amount:outstanding(r)});return;}else if(action==='convert'){await api('/convert','POST',{id});}else if(action==='renew'){openEditor('subscriptions',{}, {...r,id:undefined,starts:today(),ends:'',status:'Draft',number:undefined,nextBilling:undefined});return;}else if(action==='confirmInvoice'){await api('/invoice-action','POST',{id,action:'confirm'});}else if(action==='cancel'||action==='send'){if(action==='cancel'&&!confirm('Cancel this invoice? This keeps its billing period from being generated again.'))return;await api('/invoice-action','POST',{id,action});}else if(action==='print'){printInvoice(r);return;}await refresh();toast(action==='send'?'Invoice emailed.':'Changes saved.');}catch(e){toast(e.message);}}
function exportCSV(){const rows=[['Invoice','Customer','Currency','Total','Balance','Due','Status'],...data.invoices.map(i=>[i.number,lookup('customers',i.customerId),i.currency||'USD',i.total,outstanding(i),i.due,i.status])];const csv=rows.map(row=>row.map(v=>`"${String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='brightloop-invoices.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Invoice report exported.');}
function printInvoice(i){const invoiceMoney=n=>money(n,i.currency||'USD');const customer=i.customer||data.customers.find(c=>c.id===i.customerId),s=data.subscriptions.find(s=>s.id===i.subscriptionId),lines=i.lines?.length?i.lines:[i.line||{name:lookup('products',s?.productId)+(s?.variantName?' · '+s.variantName:''),quantity:s?.quantity,unitPrice:s?.unitPrice,subtotal:i.subtotal}],w=window.open('','_blank');if(!w){toast('Allow popups to print invoices.');return;}const rows=lines.map(line=>`<tr><td>${esc(line.name||lookup('products',line.productId))}</td><td>${esc(line.quantity||'—')}</td><td>${invoiceMoney(line.unitPrice)}</td><td>${invoiceMoney(line.subtotal??Number(line.unitPrice)*Number(line.quantity))}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><title>${esc(i.number)}</title><style>body{font:15px Arial;padding:50px;color:#202124}h1{font-weight:400}table{width:100%;border-collapse:collapse;margin-top:40px}td,th{padding:14px;text-align:left;border-bottom:1px solid #ddd}footer{margin-top:40px;color:#666}</style></head><body><h1>Brightloop Software · Invoice</h1><h2>${esc(i.number)}</h2><p>${esc(customer?.name)}<br>${esc(customer?.email)}</p><p>Issued: ${esc(i.billingDate)} · Due: ${esc(i.due)} · ${esc(i.status)}</p><table><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Amount</th></tr>${rows}<tr><td colspan="3">Discount</td><td>−${invoiceMoney(i.discount)}</td></tr><tr><td colspan="3">Tax</td><td>${invoiceMoney(i.tax)}</td></tr><tr><td colspan="3">Total</td><td>${invoiceMoney(i.total)}</td></tr><tr><td colspan="3">Balance due</td><td>${invoiceMoney(outstanding(i))}</td></tr></table><footer>${esc(i.terms||'Thank you for your business.')}</footer></body></html>`);w.document.close();w.print();}
async function boot(){app.innerHTML='<div class="loading">Loading Brightloop…</div>';if(new URLSearchParams(location.search).has('reset')){auth('reset');return;}try{const r=await api('/auth/me');user=r.user;await load();shell();}catch(error){user=null;const message=error?.message==='Please sign in.'?'':'Brightloop could not load your workspace. Check that the server and database are available, then try again.';if(message)console.error(error);auth('login',message);}}
boot();

function productVariantEditor(variants){
 const section=document.createElement('section');section.className='product-variants';section.innerHTML='<h3>Brands and variants</h3><p class="muted">Add a brand name and its extra monthly base price. A zero adjustment keeps the base price.</p><div id="variantRows"></div><button type="button" class="outline-button" id="addVariant">Add variant</button>';document.querySelector('#formFields').append(section);
 function add(v={}){const row=document.createElement('div');row.className='variant-row';row.dataset.variantId=v.id||'';row.innerHTML=`<label>Brand / variant<input data-variant-name required maxlength="100" value="${esc(v.name||'')}"></label><label>Additional price<input data-variant-price type="number" min="0" step="0.01" required value="${esc(v.extraPrice??0)}"></label><button type="button" class="text-button" aria-label="Remove variant">Remove</button>`;row.querySelector('button').onclick=()=>row.remove();section.querySelector('#variantRows').append(row);}
 variants.forEach(add);section.querySelector('#addVariant').onclick=()=>{if(section.querySelectorAll('.variant-row').length<20)add();};
}
function recordLineEditor(lines=[]){
 const old=document.querySelector('#billingLines');if(old)old.remove();const section=document.createElement('section');section.id='billingLines';section.className='product-variants';section.innerHTML='<h3>Additional product lines</h3><p class="muted">Add software, services or add-ons that should bill with this record.</p><div id="billingLineRows"></div><button type="button" class="outline-button" id="addBillingLine">Add product line</button>';document.querySelector('#formFields').append(section);
 const options=(rows,value,label='name')=>rows.map(row=>`<option value="${esc(row.id)}" ${row.id===value?'selected':''}>${esc(row[label]||row.name)}</option>`).join('');
 function add(line={}){if(section.querySelectorAll('.billing-line-row').length>=24)return;const row=document.createElement('div');row.className='billing-line-row';row.innerHTML=`<label>Product<select data-line-product required><option value="">Choose…</option>${options(data.products||[],line.productId)}</select></label><label>Plan<select data-line-plan required><option value="">Choose…</option>${options(data.plans||[],line.planId)}</select></label><label>Quantity<input data-line-quantity type="number" min="1" step="1" required value="${esc(line.quantity||1)}"></label><label>Unit price<input data-line-price type="number" min="0" step="0.01" required value="${esc(line.unitPrice??0)}"></label><label>Tax<select data-line-tax><option value="">None</option>${(data.taxes||[]).map(t=>`<option value="${esc(t.id)}" ${t.id===line.taxId?'selected':''}>${esc(t.name)} (${esc(t.rate)}%)</option>`).join('')}</select></label><button type="button" class="text-button">Remove</button>`;const product=row.querySelector('[data-line-product]'),plan=row.querySelector('[data-line-plan]'),price=row.querySelector('[data-line-price]');product.onchange=()=>{price.value=data.products.find(p=>p.id===product.value)?.price||0;};plan.onchange=()=>{const selected=data.plans.find(p=>p.id===plan.value);if(selected){product.value=selected.productId||product.value;price.value=selected.price??data.products.find(p=>p.id===selected.productId)?.price??0;}};row.querySelector('button').onclick=()=>row.remove();section.querySelector('#billingLineRows').append(row);}
 lines.forEach(add);section.querySelector('#addBillingLine').onclick=()=>add();
}
function applyQuotationTemplate(template){
 if(!template)return;const set=(name,value)=>{const field=document.querySelector(`#edit-${name}`);if(field)field.value=value??'';};const first=(template.lines||[template])[0];for(const [name,value] of Object.entries({productId:first.productId,planId:first.planId,quantity:first.quantity,unitPrice:first.unitPrice,taxId:first.taxId||'',discountId:template.discountId||'',terms:template.terms||'Net 15'}))set(name,value);const end=new Date(`${today()}T12:00:00Z`);end.setUTCDate(end.getUTCDate()+Number(template.validDays||30));set('ends',end.toISOString().slice(0,10));recordLineEditor((template.lines||[]).slice(1));
}
